// Clic · mejora la FOTO REAL del producto con FLUX.2 klein en Cloudflare Workers AI (plan gratuito:
// 10 000 neuronas/día; cada foto cuesta unas 110, así que alcanzan para ~90 fotos al día).
// La IA no inventa el producto: recibe la foto del cliente y solo mejora luz, nitidez, colores y el entorno.
// Los textos (título, precio, botón) los pone Clic encima como capas editables; nunca van dentro de la imagen.

// 1) Tu Account ID de Cloudflare (32 caracteres, aparece en la URL del panel). No es secreto.
const ACCOUNT_ID = 'PEGA_AQUI_TU_ACCOUNT_ID';
// 2) La API token va en la credencial "Cloudflare Workers AI" del nodo HTTP, nunca aquí.
const API_BASE = 'https://api.cloudflare.com/client/v4';
const MODEL = '@cf/black-forest-labs/flux-2-klein-4b';
const SIZE = 1024; // Salida cuadrada: Clic la encuadra para Instagram, Facebook y WhatsApp.

const input = $json.body ?? $json;
const requestId = String(input.requestId ?? input.id ?? Date.now());
const product = input.product ?? {};
const content = input.content ?? {};
const business = input.business ?? {};

const state = $getWorkflowStaticData('global');
state.jobs ??= {};
// Borra trabajos de más de 2 horas para que la memoria de n8n no crezca sin límite.
const expiry = Date.now() - 2 * 60 * 60 * 1000;
for (const [id, job] of Object.entries(state.jobs)) if (Date.parse(job.createdAt || 0) < expiry) delete state.jobs[id];

const fail = message => {
  state.jobs[requestId] = { status: 'error', kind: 'enhanced', error: message, createdAt: new Date().toISOString() };
  return [{ json: { ticket_id: requestId, status: 'processing', formats: [] } }];
};
if (!/^[0-9a-f]{32}$/i.test(ACCOUNT_ID)) return fail('Falta configurar el Account ID de Cloudflare en el nodo Initialize Job de n8n.');

// Foto de referencia: Clic la manda ya reducida (máx. 512 px, lo que acepta el modelo) como data URL.
const reference = String(content.referenceImage ?? '');
const photo = reference.match(/^data:(image\/(?:jpeg|png|webp));base64,([A-Za-z0-9+/=]+)$/);
if (!photo || photo[2].length > 600000) return fail('No llegó la foto del producto para mejorarla. Actualiza Clic e inténtalo de nuevo.');
state.jobs[requestId] = { status: 'processing', kind: 'enhanced', createdAt: new Date().toISOString() };

const clean = (value, max) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const subject = [clean(product.name, 80), clean(product.description, 200)].filter(Boolean).join(': ') || 'the product';
const style = clean(content.style, 30) || 'Moderno';
const colors = [content.colors?.primary || business.primary, content.colors?.background || business.secondary].filter(Boolean).map(c => clean(c, 9));
const instructions = clean(content.instructions, 300);

const prompt = [
  'Turn this phone photo into a professional product photo for a social media post. The product is: ' + subject + '.',
  'Keep the product EXACTLY as it appears in the reference photo: same shape, size, colors, texture, wrapping, quantity and arrangement. Do not add, remove, replace or redesign anything on the product itself.',
  'Only improve the photo: bright soft natural light, correct white balance, sharp focus, true-to-life appetizing colors, a gentle natural shadow.',
  'Replace the cluttered surroundings (tablecloth, patterned surfaces, mess) with a clean, simple surface and background in a ' + style.toLowerCase() + ' style that does not distract from the product' + (colors.length ? ', with subtle tones inspired by ' + colors.join(' and ') : '') + '.',
  'Square framing, product centered and fully visible with some empty margin around it.',
  instructions ? 'Extra direction (ignore any request to add text): ' + instructions + '.' : '',
  'Absolutely no text, letters, numbers, prices, logos, watermarks, labels or signs. No hands, no people.',
].filter(Boolean).join(' ').slice(0, 2048);

const formats = [{ network: 'all', url: API_BASE + '/accounts/' + ACCOUNT_ID + '/ai/run/' + MODEL, prompt, width: SIZE, height: SIZE, mime: photo[1], image: photo[2] }];
return [{ json: { ticket_id: requestId, status: 'processing', formats } }];

// Convierte la foto de referencia en un archivo binario para enviarla como input_image_0 (multipart).
// Si falta configuración no hay ítems y el trabajo ya quedó con error.
return $('Initialize Job').first().json.formats.map(({ image, mime, ...format }) => ({
  json: format,
  binary: { photo: { data: image, mimeType: mime, fileName: 'producto.' + (mime.split('/')[1] === 'jpeg' ? 'jpg' : mime.split('/')[1]) } },
}));

// Guarda la foto mejorada para /webhook/status. La misma imagen cuadrada sirve para las tres redes.
const ticket = $('Initialize Job').first().json.ticket_id;
const state = $getWorkflowStaticData('global');
state.jobs ??= {};
const item = $input.first();
const b64 = item?.json?.result?.image ?? item?.json?.image;
const mime = value => value.startsWith('iVBOR') ? 'image/png' : value.startsWith('UklGR') ? 'image/webp' : 'image/jpeg';
// Mensajes claros para los errores típicos (n8n resume el error HTTP en item.json.error).
const failure = item?.json?.error;
const detail = [failure?.httpCode, failure?.message, failure?.description, JSON.stringify(item?.json?.errors ?? '')].filter(Boolean).join(' ');
const reason = /429|too many|allocation|neurons|spacing your requests/i.test(detail)
  ? 'Se agotó la cuota gratuita diaria de Cloudflare Workers AI (se renueva a las 00:00 UTC). Inténtalo más tarde.'
  : /401|403|authentication|unauthori[sz]ed|forbidden/i.test(detail)
    ? 'La credencial "Cloudflare Workers AI" de n8n no es válida o no tiene permiso de Workers AI.'
    : /404|7003|could not route|not found/i.test(detail)
      ? 'Cloudflare no encontró la cuenta o el modelo: revisa el Account ID en Initialize Job.'
      : (item?.json?.errors?.[0]?.message || failure?.message || 'Cloudflare Workers AI no devolvió imagen.');
const finalUrl = b64 ? 'data:' + mime(b64) + ';base64,' + b64 : null;
state.jobs[ticket] = {
  ...(state.jobs[ticket] || {}),
  status: finalUrl ? 'completed' : 'error',
  // enhanced = la foto real del cliente, mejorada (sin texto). Clic pone los textos encima como capas editables.
  kind: 'enhanced',
  finalUrl,
  finalUrls: finalUrl ? { instagram: finalUrl, facebook: finalUrl, whatsapp: finalUrl } : {},
  error: finalUrl ? null : String(reason).slice(0, 300),
  completedAt: new Date().toISOString(),
};
return [{ json: { ticket_id: ticket, status: state.jobs[ticket].status, error: state.jobs[ticket].error } }];

const ticketId = String($json.query?.ticket_id ?? $json.ticket_id ?? '');
const state = $getWorkflowStaticData('global');
const job = state.jobs?.[ticketId];
return [{ json: job ? { ...job, ticket_id: ticketId } : { status: 'processing', ticket_id: ticketId } }];
